\begin{tikzpicture}
    % Sea (slightly wavy line)
    \fill[blue!30] (0,0) rectangle (10,-2);
    \draw[blue, thick] (0,-0.1) .. controls (1,-0.3) and (2,0.1) .. (3,-0.2)
    .. controls (4,-0.5) and (5,-0.1) .. (6,-0.3)
    .. controls (7,-0.1) and (8,-0.3) .. (9,-0.2)
    .. controls (10,-0.5) and (11,0.1) .. (12,-0.2);

    % Enhanced lighthouse (cartoonish style with more details)

    % Lighthouse base (stone)
    \fill[gray!50] (0.7,-0.5) rectangle (1.3,0.3);
    \draw[thick] (0.7,-0.5) -- (0.7,0.3) -- (1.3,0.3) -- (1.3,-0.5) -- cycle;

    % Lighthouse body (stripes for a more lively look)
    \fill[white] (0.7,0.3) rectangle (1.3,1);
    \fill[red!80] (0.7,1) rectangle (1.3,1.5);
    \fill[white] (0.7,1.5) rectangle (1.3,2);
    \fill[red!80] (0.7,2) rectangle (1.3,2.5);
    \fill[white] (0.7,2.5) rectangle (1.3,3);

    \draw[thick] (0.7,0.3) -- (0.7,3) -- (1.3,3) -- (1.3,0.3) -- cycle;

    % Windows on the lighthouse
    \fill[black!70] (0.9,1.2) rectangle (1.1,1.4); % first window
    \fill[black!70] (0.9,2.2) rectangle (1.1,2.4); % second window

    % Lighthouse top (lantern room)
    \fill[gray!70] (0.6,3) rectangle (1.4,3.3);
    \draw[thick] (0.6,3) -- (1.4,3);
    \draw[thick] (0.6,3.3) -- (1.4,3.3);

    % Lighthouse roof (dome-shaped top)
    \fill[red!80] (0.65,3.3) -- (1.35,3.3) -- (1,3.8) -- cycle;

    % Lighthouse light
    \fill[yellow] (1,3.15) circle (0.1);

    % Lighthouse light beams (enhanced beams with glow effect)
    \draw[yellow!80, thick] (1,3.15) -- (0,4);
    \draw[yellow!80, thick] (1,3.15) -- (2,4);

    % Lighthouse door
    \fill[brown!80] (0.9,-0.5) rectangle (1.1,-0.2);
    \draw[thick] (0.9,-0.5) -- (0.9,-0.2) -- (1.1,-0.2) -- (1.1,-0.5) -- cycle;

    \foreach \x in {3.5, 5.5, 7.5} {
        \draw[blue!60,thick] (\x,-0.5) .. controls (\x+0.3,-0.6) and (\x+0.7,-0.4) .. (\x+1,-0.5);
    }

    % Second boat (smaller and farther away)
    \fill[brown!70] (7,-0.5) .. controls (7.1,-0.9) and (7.9,-0.9) .. (8,-0.5) -- cycle; % hull
    \draw[thick] (7,-0.5) .. controls (7.1,-0.9) and (7.9,-0.9) .. (8,-0.5) -- cycle;

    \draw[thick] (7.5,-0.5) -- (7.5,0.2); % mast
    \fill[white] (7.5,-0.1) .. controls (8,0) and (8,0.1) .. (7.5,0.2) -- cycle; % sail
    \draw[thick] (7.5,-0.1) .. controls (8,0) and (8,0.1) .. (7.5,0.2) -- cycle;

    % Flag for the second boat
    \fill[red] (7.5,0.2) -- (7.7,0.3) -- (7.5,0.4) -- cycle;

    % Marking points A (top of lighthouse), B (bottom of lighthouse), C (first boat), D (second boat)
    \fill[black] (1,3.5) circle (0.05) node[above] {A};  % Point A (top of lighthouse)
    \fill[black] (1,-0.5) circle (0.05) node[below] {B}; % Point B (bottom of lighthouse)
 % Point C (position of boat 1)
    \fill[black] (7.5,-0.5) circle (0.05) node[below] {D}; % Point D (position of boat 2)

    % Draw lines connecting A-B, A-C, A-D
    \draw[thick] (1,3.5) -- (1,-0.5);  % Line AB% Line AC
    \draw[thick] (1,3.5) -- (7.5,-0.5); % Line AD

    % Draw line B-C-D
    \draw[thick] (1,-0.5) -- (5,-0.5) -- (7.5,-0.5);  % Line BCD

    % Add a line x parallel to BC through A
% Dashed line x, parallel to BC

    % Add a smiling sun in the sky
    \fill[yellow] (9,3.5) circle (0.5); % sun body
    \draw (9,3.7) arc[start angle=45, end angle=135, radius=0.2]; % smiling face
    \fill[black] (8.8,3.6) circle (0.05); % left eye
    \fill[black] (9.2,3.6) circle (0.05); % right eye
    \foreach \angle in {0,45,...,315} {
        \draw[thick, yellow] (9,3.5) -- ++(\angle:0.8);
    }

\end{tikzpicture}

